import boto3

def archive_metric_snapshots(bucket_name, local_directory):
    s3 = boto3.client('s3')
    for file_name in os.listdir(local_directory):
        if file_name.endswith('.json'):
            file_path = os.path.join(local_directory, file_name)
            s3.upload_file(file_path, bucket_name, file_name)
            print(f'Archived {file_name} to {bucket_name}')

if __name__ == '__main__':
    bucket_name = 'your-s3-bucket-name'
    local_directory = '/path/to/local/directory'
    archive_metric_snapshots(bucket_name, local_directory)

import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': text
            }
        ]
    )
    return response

if __name__ == '__main__':
    sample_text = 'This is a sample text to check for unsafe content.'
    result = check_unsafe_text(sample_text)
    print(result)

from typing import Any, Dict, List

def create_request(metric_name: str, dimensions: Dict[str, str], value: float, timestamp: int) -> Dict[str, Any]:
    return {
        'MetricName': metric_name,
        'Dimensions': dimensions,
        'Value': value,
        'Timestamp': timestamp
    }

def parse_response(response: Dict[str, Any]) -> Dict[str, Any]:
    if 'Metrics' in response:
        return response['Metrics'][0]
    return {}

def normalize_data(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    normalized_data = []
    for item in data:
        normalized_item = {
            'MetricName': item.get('MetricName', ''),
            'Dimensions': item.get('Dimensions', {}),
            'Value': item.get('Value', 0.0),
            'Timestamp': item.get('Timestamp', 0)
        }
        normalized_data.append(normalized_item)
    return normalized_data

import boto3

def query_metric_data(namespace, metric_name, dimensions):
    cloudwatch = boto3.client('cloudwatch')
    response = cloudwatch.get_metric_data(
        MetricDataQueries=[
            {
                'Id': 'm1',
                'MetricStat': {
                    'Metric': {
                        'Namespace': namespace,
                        'MetricName': metric_name,
                        'Dimensions': dimensions
                    },
                    'Period': 300,
                    'Stat': 'Average'
                }
            }
        ],
        StartTime=datetime.datetime.utcnow() - datetime.timedelta(minutes=60),
        EndTime=datetime.datetime.utcnow()
    )
    return response

if __name__ == '__main__':
    namespace = 'AWS/EC2'
    metric_name = 'CPUUtilization'
    dimensions = [{'Name': 'InstanceId', 'Value': 'i-1234567890abcdef0'}]
    result = query_metric_data(namespace, metric_name, dimensions)
    print(result)
